\label{thmext}
    Let $\omega$ be a regular domain as in Definition \ref{defregdom}. Let $\chi(x,D)$ be a pseudodifferential microlocalizer adapted to $\omega$.  Then, there holds, for any $\eta > 0$,
    \[\forall \delta \geqslant \lambda^{-1/3 + \eta}, \qquad \left\|P_{\lambda,\delta} \chi(x,D) \right\|_{L^2(M) \to L^4(M)} \lesssim \lambda^{1/8} \delta^{1/8} \ln(\lambda)^{1/4}.\]

\begin{itemize}
        \item In the case where $\Sigma = \mathbb{S}^2$ is the two-sphere equipped with a metric of revolution, which is \textit{simple} (see \cite{de1980spectre}) and satisfies the \textit{twist hypothesis} (see \cite{bleher1994distribution}), then $\Omega$ equals the cotangent space of $\Sigma$ from which is removed the two-dimensional subsets of cotangent vectors of the equator. Moreover, $\Omega$ is itself a regular domain, since the twist hypothesis guarantees the nonzero curvature assumption, and all Lagrangian tori have fold-type singularities, except for the Lagrangian torus of vertical cotangent vectors. Thus, for any compact subset $K$ of $\Sigma$ which doesn't contain a pole or intersects the equator, Theorem \ref{thmext} gives a bound on the $L^2(\Sigma) \to L^4(K)$ norm of spectral projectors. For a justification of the above facts, one may consult \cite{chabert2025infty}, or \cite{chabert2025bounds} for a more detailed introduction.

        \item Let $\Sigma = \mathbb{T}^2$ be a 2D-torus equipped with a metric of revolution, which we may write as $g = (dx^1)^2 + f(x^1) (dx^2)^2$ in canonical coordinates $(x^1,x^2)$. Assume that either $f$ is constant, either that its stationary points are isolated. Then, the above theorem still applies after microlocalizing away from the vectors which are cotangent to the 1-dimensional submanifold $\{f' = 0\}$, and away from generically exceptional Lagrangian submanifolds for which the curvature of the curve $\{K =1\}$ vanishes.
    \end{itemize}

\label{Lemmstatphase}
	For any $n\in Z$, for any $N\geqslant 0$ and for any $r - \mu_n \gtrsim \lambda^{-2/3 + \kappa}$, there holds
	\begin{equation}\label{statphaseforJn}
	\left|\lambda_n^{1/2} J_n(\lambda_n r) - \frac{\cos(\lambda_n(\mu_n \alpha_n - r \sin(\alpha_n)))}{(r^2 - \mu_n^2)^{1/4}} a_{n,N,\lambda}(r) \right| \lesssim_{\kappa,N} \lambda^{-N},
	\end{equation}
	where $\alpha_n(r)$ is defined by
	\[\alpha_n(r) := \arccos(\mu_n / r),\]
	and where $a_{n,N,\lambda}(r)$ is a smooth function such that
	\begin{equation}\label{deranearcaus}
	    \left|\frac{d^K}{dr^K} a_{n,N,\lambda}(r)\right| \lesssim_{\varepsilon,\kappa, N} (r-\mu_n)^{-K}.
	\end{equation}

